            {
                <p class="meta-info">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-container">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in securitySettings.Sessions)
                            {
                                var isFirst = session.Id == securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>@session.Device @if (isFirst) { <span class="current-badge">Current</span> }</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (!isFirst)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p>No active sessions found.</p>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance Settings</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => { selectedTheme = theme; }" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => { selectedFontSize = size; }" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="selectedLanguage">
                    @foreach (var lang in availableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <label class="switch">
                        <input type="checkbox" @bind="compactMode" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Live Preview</h3>
            <div class="live-preview @(selectedTheme.ToLower())-theme @(compactMode ? "compact" : "")"
                 style="font-size: @GetPreviewFontSize();">
                <div class="preview-header">
                    <strong>Preview Panel</strong>
                    <span class="preview-meta">Theme: @selectedTheme | Font: @selectedFontSize | Lang: @selectedLanguage</span>
                </div>
                <p class="preview-text">
                    This is how your content will appear with the selected settings.
                    The quick brown fox jumps over the lazy dog.
                </p>
                <div class="preview-actions">
                    <button class="preview-btn">Sample Button</button>
                    <span class="preview-link">Sample Link</span>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewFontSize() => selectedFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };
}
"}

