        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId, string device)
    {
        confirmTitle = "Revoke Session";
        confirmMessage = $"Are you sure you want to revoke the session on \"{device}\"? This will sign out that device immediately.";
        confirmCallback = async () => await RevokeSession(sessionId);
        showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "success");
    }

    private async Task ConfirmAction()
    {
        showConfirmDialog = false;
        if (confirmCallback is not null)
        {
            await confirmCallback();
        }
    }

    private void CancelConfirm()
    {
        showConfirmDialog = false;
        confirmCallback = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        toastMessage = null;
    }

    // Render fragments
    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url-display">@profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="() => ToggleChannelMute(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security Settings</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="ToggleChangePassword">
                    <span>Change Password</span>
                    <span class="expand-icon">@(changePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group" style="margin-top: 1.5rem;">
                <label class="toggle-label">
                    <span>
                        Two-Factor Authentication
                        <span class="status-badge @(twoFactorEnabled ? "enabled" : "disabled")">
                            @(twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </span>
                    <label class="switch">
                        <input type="checkbox" @bind="twoFactorEnabled" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            @if (securitySettings?.LastPasswordChange is not null)
            {
                <p class="meta-info">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-container">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in securitySettings.Sessions)
                            {
                                var isFirst = session.Id == securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>@session.Device @if (isFirst) { <span class="current-badge">Current</span> }</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (!isFirst)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p>No active sessions found.</p>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance Settings</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => { selectedTheme = theme; }" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => { selectedFontSize = size; }" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="selectedLanguage">
                    @foreach (var lang in availableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <label class="switch">
                        <input type="checkbox" @bind="compactMode" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Live Preview</h3>
            <div class="live-preview @(selectedTheme.ToLower())-theme @(compactMode ? "compact" : "")"
                 style="font-size: @GetPreviewFontSize();">
                <div class="preview-header">
                    <strong>Preview Panel</strong>
                    <span class="preview-meta">Theme: @selectedTheme | Font: @selectedFontSize | Lang: @selectedLanguage</span>
                </div>
                <p class="preview-text">
                    This is how your content will appear with the selected settings.
                    The quick brown fox jumps over the lazy dog.
                </p>
                <div class="preview-actions">
                    <button class="preview-btn">Sample Button</button>
                    <span class="preview-link">Sample Link</span>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewFontSize() => selectedFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };
}

